//! Consultation sessions: a pack simulated from the catalogue, without any
//! project, work session, autosave or recovery.
//!
//! A consultation is identified by a token generated by the interface for
//! each launch. Its life cycle is `preparing → ready → closing → closed`, or
//! `failed`; only a `ready` consultation serves media, and only the media of
//! its own table. Its temporary resources live in a folder it owns,
//! `<app cache>/catalogue/staging/consultations/<token>/`, removed at its
//! closing, at a failed preparation, for a result arriving after its closing,
//! and at the next start of the application (no consultation survives it).
//!
//! The content token of the source is checked again at each media read: a
//! file changed while listening expires the consultation instead of mixing a
//! former graph with new media.
use super::{
    materialize::{self, Media},
    target::{current_token, Target},
};
use crate::services::catalogue::{store::Store, Result};
use crate::support::user_message::{codes, UserMessage};
use serde::Serialize;
use serde_json::Value;
use std::{
    collections::HashMap,
    path::{Path, PathBuf},
    sync::{
        atomic::{AtomicBool, Ordering},
        Arc, Condvar, Mutex,
    },
    time::Duration,
};

/// Folder of the consultations, under the application cache.
pub fn consultations_root(cache: &Path) -> PathBuf {
    cache
        .join("catalogue")
        .join("staging")
        .join("consultations")
}

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Status {
    Preparing,
    Ready,
    Closing,
    Failed,
}

struct Ready {
    pinned: PathBuf,
    token: String,
    media: HashMap<String, Media>,
}

struct Entry {
    status: Status,
    cancel: Arc<AtomicBool>,
    readers: usize,
    ready: Option<Ready>,
}

#[derive(Default)]
struct State {
    live: HashMap<String, Entry>,
    /// Folders of closed consultations whose removal failed, retried later.
    retry: Vec<PathBuf>,
}

/// Removal of an owned folder; replaceable in tests to simulate a failure.
type Remover = Box<dyn Fn(&Path) -> std::io::Result<()> + Send + Sync>;

pub struct Registry {
    root: PathBuf,
    remover: Remover,
    state: Mutex<State>,
    idle: Condvar,
    timeout: Duration,
}

#[derive(Debug, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct Closed {
    pub closed: bool,
    pub cleanup_failed: bool,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub cleanup: Option<UserMessage>,
}

#[derive(Debug, Serialize)]
#[serde(rename_all = "camelCase")]
pub struct ConsultationHandle {
    pub consultation_id: String,
    pub exemplar_id: String,
    pub source_revision: i64,
    pub kind: &'static str,
    pub graph: Value,
    pub start_id: Option<String>,
    pub media_count: usize,
    /// Media type of each media identifier.
    pub media_types: HashMap<String, &'static str>,
}

fn expired() -> UserMessage {
    UserMessage::new(codes::CATALOG_CONSULTATION_EXPIRED)
}

fn lock_error<T>(_: T) -> UserMessage {
    expired()
}

/// A launch token names a folder: only a plain identifier is accepted.
fn valid_token(token: &str) -> bool {
    !token.is_empty()
        && token.len() <= 64
        && token
            .bytes()
            .all(|byte| byte.is_ascii_alphanumeric() || byte == b'-')
}

/// Removes a folder; an absent folder is already clean.
fn remove(path: &Path) -> std::io::Result<()> {
    match std::fs::remove_dir_all(path) {
        Err(error) if error.kind() != std::io::ErrorKind::NotFound => Err(error),
        _ => Ok(()),
    }
}

impl Registry {
    /// Opens the registry of `root` and removes every leftover consultation
    /// folder: none survives a restart. Nothing outside `root` is touched.
    pub fn new(root: PathBuf) -> Self {
        Self::with_timeout(root, super::super::probe::PROBE_TIMEOUT)
    }

    pub(crate) fn with_timeout(root: PathBuf, timeout: Duration) -> Self {
        if let Err(error) = remove(&root) {
            log::warn!(target: "catalogue_consultation", "orphan consultations not removed: {error}");
        }
        Self {
            root,
            remover: Box::new(remove),
            state: Mutex::new(State::default()),
            idle: Condvar::new(),
            timeout,
        }
    }

    #[cfg(test)]
    pub(crate) fn with_remover(mut self, remover: Remover) -> Self {
        self.remover = remover;
        self
    }

    fn folder(&self, token: &str) -> PathBuf {
        self.root.join(token)
    }

    #[cfg(test)]
    pub fn status(&self, token: &str) -> Option<Status> {
        self.state
            .lock()
            .ok()?
            .live
            .get(token)
            .map(|entry| entry.status)
    }

    /// Registers a launch: one consultation at a time, the others are closed.
    pub fn begin(&self, token: &str) -> Result<(PathBuf, Arc<AtomicBool>)> {
        if !valid_token(token) {
            return Err(expired());
        }
        let others = {
            let mut state = self.state.lock().map_err(lock_error)?;
            if state.live.contains_key(token) {
                return Err(expired());
            }
            let others = state.live.keys().cloned().collect::<Vec<_>>();
            let cancel = Arc::new(AtomicBool::new(false));
            state.live.insert(
                token.to_owned(),
                Entry {
                    status: Status::Preparing,
                    cancel: Arc::clone(&cancel),
                    readers: 0,
                    ready: None,
                },
            );
            (others, cancel)
        };
        let (others, cancel) = others;
        for other in others {
            self.close(&other);
        }
        let folder = self.folder(token);
        if let Err(error) = std::fs::create_dir_all(&folder) {
            self.discard(token);
            return Err(UserMessage::from(error.to_string()));
        }
        Ok((folder, cancel))
    }

    /// Publishes a prepared consultation. A launch closed or replaced in the
    /// meantime is rejected and its resources removed.
    pub fn publish(
        &self,
        token: &str,
        ready_for: (PathBuf, String),
        prepared: &materialize::Prepared,
    ) -> Result<()> {
        let accepted = {
            let mut state = self.state.lock().map_err(lock_error)?;
            match state.live.get_mut(token) {
                Some(entry)
                    if entry.status == Status::Preparing
                        && !entry.cancel.load(Ordering::Relaxed) =>
                {
                    entry.status = Status::Ready;
                    entry.ready = Some(Ready {
                        pinned: ready_for.0,
                        token: ready_for.1,
                        media: prepared.media.clone(),
                    });
                    true
                }
                _ => false,
            }
        };
        if accepted {
            Ok(())
        } else {
            let _ = (self.remover)(&self.folder(token));
            Err(expired())
        }
    }

    /// A failed preparation leaves nothing behind.
    pub fn discard(&self, token: &str) {
        if let Ok(mut state) = self.state.lock() {
            if state
                .live
                .get(token)
                .is_some_and(|entry| entry.status == Status::Preparing)
            {
                state.live.remove(token);
            }
        }
        if !self.is_live(token) {
            let _ = (self.remover)(&self.folder(token));
        }
    }

    fn is_live(&self, token: &str) -> bool {
        self.state
            .lock()
            .map(|state| state.live.contains_key(token))
            .unwrap_or(false)
    }

    /// Bytes and media type of one media of a ready consultation.
    pub fn read(&self, token: &str, media_id: &str) -> Result<(Vec<u8>, &'static str)> {
        let (media, pinned, expected) = {
            let mut state = self.state.lock().map_err(lock_error)?;
            let entry = state.live.get_mut(token).ok_or_else(expired)?;
            if entry.status != Status::Ready {
                return Err(expired());
            }
            let ready = entry.ready.as_ref().ok_or_else(expired)?;
            let media = ready.media.get(media_id).cloned().ok_or_else(expired)?;
            let found = (media, ready.pinned.clone(), ready.token.clone());
            entry.readers += 1;
            found
        };
        let unchanged = current_token(&pinned, self.timeout).as_deref() == Some(expected.as_str());
        let result = if unchanged {
            media.read().map(|bytes| (bytes, media.mime()))
        } else {
            Err(expired())
        };
        let mut state = self.state.lock().map_err(lock_error)?;
        if let Some(entry) = state.live.get_mut(token) {
            entry.readers = entry.readers.saturating_sub(1);
            if !unchanged && entry.status == Status::Ready {
                entry.status = Status::Failed;
            }
        }
        self.idle.notify_all();
        result
    }

    /// Closes a consultation: idempotent, cancels a preparation, waits for
    /// the reads in progress, then removes the owned resources. A removal
    /// that fails is reported and retried at the next closing.
    pub fn close(&self, token: &str) -> Closed {
        let retry = match self.state.lock() {
            Ok(mut state) => {
                if let Some(entry) = state.live.get_mut(token) {
                    entry.cancel.store(true, Ordering::Relaxed);
                    entry.status = Status::Closing;
                }
                let mut state = match self.idle.wait_while(state, |state| {
                    state.live.get(token).is_some_and(|entry| entry.readers > 0)
                }) {
                    Ok(state) => state,
                    Err(poisoned) => poisoned.into_inner(),
                };
                state.live.remove(token);
                let live = state
                    .live
                    .keys()
                    .map(|id| self.folder(id))
                    .collect::<Vec<_>>();
                let retry = std::mem::take(&mut state.retry);
                retry
                    .into_iter()
                    .filter(|path| !live.contains(path))
                    .collect()
            }
            Err(_) => Vec::new(),
        };
        let mut failed = Vec::new();
        let folder = if valid_token(token) {
            Some(self.folder(token))
        } else {
            None
        };
        let mut cleanup = None;
        if let Some(folder) = folder {
            if let Err(error) = (self.remover)(&folder) {
                log::warn!(target: "catalogue_consultation", "consultation not removed: {error}");
                cleanup = Some(
                    UserMessage::new(codes::CATALOG_CLEANUP_FAILED)
                        .param("path", crate::support::paths::path_for_frontend(&folder))
                        .with_detail(error.to_string()),
                );
                failed.push(folder);
            }
        }
        for path in retry {
            if (self.remover)(&path).is_err() {
                failed.push(path);
            }
        }
        if !failed.is_empty() {
            if let Ok(mut state) = self.state.lock() {
                state.retry.extend(failed);
            }
        }
        Closed {
            closed: true,
            cleanup_failed: cleanup.is_some(),
            cleanup,
        }
    }

    /// Folders still waiting for a removal (tests).
    #[cfg(test)]
    pub fn pending_cleanups(&self) -> Vec<PathBuf> {
        self.state
            .lock()
            .map(|state| state.retry.clone())
            .unwrap_or_default()
    }
}

/// Request of `catalogue_open_consultation`.
pub struct Request<'a> {
    pub consultation_id: &'a str,
    pub exemplar_id: &'a str,
    pub expected_revision: i64,
    /// Project as read by the interface's read-only loader: the normalized
    /// menu project, or the resolved media bindings of a graph project.
    pub project_json: Option<&'a str>,
}

fn revalidate(store: &Store, request: &Request<'_>, timeout: Duration) -> Result<(Target, String)> {
    let target = store.resolve_target(request.exemplar_id, request.expected_revision)?;
    store.require_active_source(&target.path)?;
    let token = target.require_unchanged(timeout)?;
    Ok((target, token))
}

/// Revalidates the exemplar, prepares its consultation and publishes it.
/// The source must hold the same content before and after the preparation;
/// otherwise nothing is published.
pub fn open(
    registry: &Registry,
    store: &Store,
    request: Request<'_>,
) -> Result<ConsultationHandle> {
    let (folder, cancel) = registry.begin(request.consultation_id)?;
    let prepared = (|| {
        let (target, token) = revalidate(store, &request, registry.timeout)?;
        let workspaces = store.workspace_roots()?;
        let prepared = materialize::prepare(
            Some(store),
            &target,
            request.project_json,
            &workspaces,
            &folder,
            &cancel,
        )?;
        if target.require_unchanged(registry.timeout)? != token {
            return Err(super::target::changed(&target.display_path()));
        }
        Ok((target, token, prepared))
    })();
    let (target, token, prepared) = match prepared {
        Ok(prepared) => prepared,
        Err(error) => {
            registry.discard(request.consultation_id);
            return Err(error);
        }
    };
    registry.publish(
        request.consultation_id,
        (target.path.clone(), token),
        &prepared,
    )?;
    Ok(ConsultationHandle {
        consultation_id: request.consultation_id.to_owned(),
        exemplar_id: request.exemplar_id.to_owned(),
        source_revision: request.expected_revision,
        kind: prepared.kind,
        media_count: prepared.media.len(),
        media_types: prepared
            .media
            .iter()
            .map(|(id, media)| (id.clone(), media.mime()))
            .collect(),
        graph: prepared.graph,
        start_id: None,
    })
}
